/**
 * dsh-conversation-recorder —— 轮次序号规则（纯函数，SPEC §6）。
 *
 * 总则：`seq` = **该会话在磁盘上已存在的最大序号 + 1**。
 *
 * 为什么不是「已落盘轮次**个数** + 1」（0.2.3 及以前的规则）：个数口径下，
 * 一旦磁盘上出现「有洞」的序号集合（例如 `0001,0002,0004`——0003 那一轮
 * 因为写盘失败/被删/外部放置而缺席），个数是 3，于是下一个序号算成 `0003`；
 * 而 `0003.md` 并不存在这件事本身就是「洞已存在」的证据。个数口径把洞
 * **填掉**（旧轮次的序号被新材料顶替，链上的轮次身份会漂移），更糟的是
 * 当序号集合的最大值远大于个数时（历史产物 `00-1.md`、手工放置的文件），
 * 后续序号会长期低于磁盘最大序号，跟「已有文件不覆写」这条死规矩互锁，
 * **被跳过的轮次会永久卡死后续记录**。取「磁盘最大序号 + 1」后序号只增不减：
 * 洞被跳过（不回填、不顶替），链继续向前。
 *
 * 与旧规则的关系：**磁盘无洞时逐字等价**（`max = 个数` ⇒ `max + 1 = 个数 + 1`）。
 * 落盘前先把磁盘上的实际序号集合读进来（`format.scanTurnSeqs`），故本规则也是
 * 「磁盘是权威」的一种写法。
 *
 * 本文档对应 SPEC §6；`seq <= 0` 拒绝落盘的要求保留在这里（与引擎的
 * 「拒绝覆写 / 写盘失败丢弃该轮」两条死规矩并列）。
 */
/** 下一个序号的判定结果。 */
export interface NextSeqResult {
    /** 下一个可用的轮次序号（4 位零填充前的整数）。 */
    readonly seq: number;
    /** true = 拒绝落盘（`seq <= 0`；调用方丢弃该轮、不写文件、不回填任何计数）。 */
    readonly rejected: boolean;
}
/**
 * 由「该会话磁盘上已存在的序号集合」算下一个序号。
 *
 * - 入参数组里 `<= 0` 的元素一律**忽略**（历史产物的负序号命名 `00-1.md` 等绝不能参与
 *   取最大值，否则 `max` 会被拉低到 0 附近，序号倒退）。
 * - 数组为空（全新会话 / 目录不存在）→ `seq = 1`（首轮）。
 * - 否则 `seq = max(已存在序号) + 1`。
 * - 本函数**不做停摆检测**（不判断「磁盘上序号是否已经用尽」）；只按上述规则给出结果。
 *
 * 纯函数、零副作用：同一个人参数组永远得到同一个结果。
 *
 * @param existing - 该会话磁盘上已存在的轮次序号（顺序无关，允许重复与非法值）
 * @returns `{ seq, rejected }`；`rejected` 为 true 时调用方不得落盘
 */
export declare function nextSeq(existing: readonly number[]): NextSeqResult;
